<template>
  <view class="login-page">
    <view class="login-container">
      <view class="login-header">
        <image class="logo" src="/static/images/logo.png" mode="aspectFit"></image>
        <text class="title">稽古云语</text>
        <text class="subtitle">探索中华文明，传承历史记忆</text>
      </view>

      <view class="login-form">
        <button class="wechat-login-btn" @click="handleWechatLogin">
          <text class="wechat-login-text">微信授权登录</text>
        </button>

        <view class="register-tip">
          <text class="tip-text">还没有账号？</text>
          <text class="register-link" @click="goToRegister">立即注册</text>
        </view>
      </view>

      <view class="login-footer">
        <text class="agreement-text">登录即表示同意</text>
        <text class="agreement-link">《用户协议》</text>
        <text class="agreement-text">和</text>
        <text class="agreement-link">《隐私政策》</text>
      </view>
    </view>

    <Loading :visible="loading" text="登录中..." />
  </view>
</template>

<script setup>
import { ref } from 'vue'
import { useUserStore } from '@/stores/user.js'
import { authApi, userApi } from '@/common/api/index.js'
import Loading from '@/components/Loading/Loading.vue'

const userStore = useUserStore()

const loading = ref(false)

const handleWechatLogin = async () => {
  loading.value = true

  try {
    // 调用微信授权登录
    uni.login({
      provider: 'weixin',
      success: async (loginRes) => {
        console.log('微信登录成功:', loginRes)
        
        // 这里应该调用后端接口，使用code进行登录
        const authRes = await authApi.wechatLogin({
          code: loginRes.code
        })
        
        userStore.setToken(authRes.data.token)
        if (authRes.data.refreshToken) {
          userStore.setRefreshToken(authRes.data.refreshToken)
        }

        const userRes = await userApi.getMe()
        userStore.setUserInfo(userRes.data)

        uni.showToast({
          title: '登录成功',
          icon: 'success'
        })

        setTimeout(() => {
          uni.switchTab({
            url: '/pages/index/index'
          })
        }, 1500)
      },
      fail: (err) => {
        console.error('微信登录失败:', err)
        uni.showToast({
          title: '微信登录失败，请重试',
          icon: 'none'
        })
      },
      complete: () => {
        loading.value = false
      }
    })
  } catch (error) {
    console.error('登录失败:', error)
    uni.showToast({
      title: '登录失败，请重试',
      icon: 'none'
    })
    loading.value = false
  }
}

const goToRegister = () => {
  uni.navigateTo({
    url: '/pages/register/register'
  })
}
</script>

